<script>
const returnUrl=@json(route('user.perpustakaan.loans.return',['userId'=>$userId,'id'=>'__ID__']));
function openReturn(btn){const d=JSON.parse(btn.dataset.loan);const f=document.getElementById('returnForm');f.action=returnUrl.replace('__ID__',d.id);let html='';d.items.forEach(function(i){html+='<div class="row g-2 align-items-center mb-2"><div class="col-md-6"><div class="fw-semibold">'+i.title+'</div><div class="text-muted small">'+i.code+'</div></div><div class="col-md-6"><select name="conditions['+i.id+']" class="form-select form-select-sm"><option value="baik">Baik</option><option value="rusak_ringan">Rusak ringan</option><option value="rusak_sedang">Rusak sedang</option><option value="rusak_berat">Rusak berat</option><option value="lost">Hilang</option></select></div></div>';});document.getElementById('returnItems').innerHTML=html;new bootstrap.Modal(document.getElementById('returnModal')).show();}
</script>
